function n(){return[{title:"导出ID",dataIndex:"id",width:90},{title:"模型ID",dataIndex:"model_id",width:100,align:"center"},{title:"模型名称",dataIndex:"model_name",width:150,customRender:({record:e})=>{const t=e.model_name||`模型${e.model_id}`,a=e.model_version;return a?`${t}（v${a}）`:t}},{title:"导出格式",dataIndex:"format",width:120,align:"center",customRender:({text:e})=>({onnx:"ONNX",openvino:"OpenVINO"})[e]||e?.toUpperCase()||"--"},{title:"状态",dataIndex:"status",width:120,align:"center",customRender:({text:e})=>({PENDING:{text:"等待中",color:"default"},PROCESSING:{text:"处理中",color:"processing"},COMPLETED:{text:"已完成",color:"success"},FAILED:{text:"失败",color:"error"}}[e]||{text:e||"--",color:"default"}).text},{title:"创建时间",dataIndex:"created_at",width:180,align:"center",customRender:({text:e})=>o(e)},{width:150,title:"操作",dataIndex:"action",fixed:"right"}]}function l(){return{labelWidth:80,baseColProps:{span:6},actionColOptions:{span:6},schemas:[{field:"model_name",label:"模型名称",component:"Input",componentProps:{placeholder:"请输入模型名称",allowClear:!0}},{field:"status",label:"状态",component:"Select",componentProps:{placeholder:"请选择状态",allowClear:!0,options:[{label:"等待中",value:"PENDING"},{label:"处理中",value:"PROCESSING"},{label:"已完成",value:"COMPLETED"},{label:"失败",value:"FAILED"}]}}]}}function o(e){if(!e)return"--";try{const t=new Date(e);return isNaN(t.getTime())?e:t.toLocaleDateString("zh-CN")+" "+t.toLocaleTimeString("zh-CN",{hour12:!1})}catch{return e}}export{n as getBasicColumns,l as getFormConfig};
